const $=id=>document.getElementById(id),fmt=(n,d=0)=>n==null?'Unavailable':n.toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d}),usd=n=>n==null?'Unavailable':'$'+(Math.abs(n)>=1e9?(n/1e9).toFixed(2)+'B':Math.abs(n)>=1e6?(n/1e6).toFixed(2)+'M':Math.abs(n)>=1e3?(n/1e3).toFixed(1)+'K':n.toFixed(2)),pct=(n,d=1)=>n==null?'Unavailable':(n*100).toFixed(d)+'%',signed=n=>n==null?'—':(n>=0?'+':'')+pct(n),label=m=>new Date(m+'-01T00:00:00Z').toLocaleDateString('en-US',{month:'short',year:'numeric',timeZone:'UTC'}),colors={volume:'#248365',fees:'#456bed',revenue:'#d48a43',buy:'#9b76b7'},names={volume:'Volume',fees:'Fees',revenue:'Revenue',buy:'Buybacks'};let D,selected,view='volume';
function chart(id,lines,labels,format,threshold=null){const el=$(id),W=1000,H=280,L=80,R=975,T=24,B=235;el.setAttribute('viewBox',`0 0 ${W} ${H}`);const vv=lines.flatMap(s=>s.values.filter(Number.isFinite));if(!vv.length){el.innerHTML='<text x="30" y="80">No complete series available.</text>';return}const max=Math.max(...vv,threshold||0)*1.12,min=Math.min(0,...vv),x=i=>L+i*(R-L)/Math.max(1,labels.length-1),y=v=>B-(v-min)/(max-min||1)*(B-T);let s='';for(let j=0;j<5;j++){let v=min+(max-min)*j/4;s+=`<line x1="${L}" x2="${R}" y1="${y(v)}" y2="${y(v)}" stroke="#e3e9e3"/><text x="${L-10}" y="${y(v)+4}" text-anchor="end" font-size="11" fill="#74827b">${format(v)}</text>`}if(threshold!=null)s+=`<line x1="${L}" x2="${R}" y1="${y(threshold)}" y2="${y(threshold)}" stroke="#74827b" stroke-dasharray="4 5"/>`;lines.forEach(a=>{let path='',segment=[];a.values.forEach((v,i)=>{if(Number.isFinite(v))segment.push([x(i),y(v)]);else{path+=window.NearCurves.path(segment);segment=[]}});path+=window.NearCurves.path(segment);s+=`<path d="${path}" fill="none" stroke="${a.color}" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/>`;a.values.forEach((v,i)=>{if(Number.isFinite(v))s+=`<circle cx="${x(i)}" cy="${y(v)}" r="5" opacity="0" fill="${a.color}" onpointerenter="this.setAttribute('opacity','1')" onpointerleave="this.setAttribute('opacity','0')" onfocus="this.setAttribute('opacity','1')" onblur="this.setAttribute('opacity','0')"><title>${labels[i]} · ${a.name}: ${format(v)}</title></circle>`})});labels.forEach((v,i)=>{if(labels.length<12||i%Math.ceil(labels.length/7)===0||i===labels.length-1)s+=`<text x="${x(i)}" y="265" text-anchor="middle" font-size="11" fill="#74827b">${v}</text>`});el.innerHTML=s;el.querySelectorAll('circle').forEach(point=>{point.setAttribute('tabindex','0');const title=point.querySelector('title')?.textContent;point.setAttribute('aria-label',title||'Chart observation');point.querySelector('title')?.remove();const show=e=>{const tip=$('chartTip');if(!tip)return;tip.textContent=title;tip.hidden=false;const box=point.getBoundingClientRect();tip.style.left=Math.min(window.innerWidth-260,e.clientX||box.x)+'px';tip.style.top=Math.max(10,(e.clientY||box.y)-45)+'px';};point.onpointermove=show;point.onfocus=show;point.onpointerleave=point.onblur=()=>{if($('chartTip'))$('chartTip').hidden=true};});}
function render(){const m=D.months[selected],growth=m.growth||{};$('periodRange').textContent='';$('period').title='Records through '+m.through+' UTC';$('monthLive').hidden=m.complete||m.month!==new Date().toISOString().slice(0,7);$('monthLive').title='Month in progress · recorded through '+m.through+' UTC';const issues=m.notes.filter(x=>x.includes('below 10%')||x.includes('differs'));$('quality').hidden=!issues.length;$('quality').title=issues.join(' ');$('quality').setAttribute('aria-label',issues.join(' ')||'Data quality note');$('cards').innerHTML=['volume','fees','revenue','buy'].map(k=>`<div class="card"><div class="label">${names[k]}</div><div class="value">${k==='buy'?fmt(m[k]):usd(m[k])}${k==='buy'?'<small> NEAR</small>':''}</div>${growth[k]!=null?`<div class="delta ${growth[k]<0?'negative':''}">${signed(growth[k])} <span class="metricfoot">vs previous month</span></div>`:''}</div>`).join('');const feeCard=$('cards').children[1];if(issues.length)feeCard.title=issues.join(' ');drawGrowth();}
function drawGrowth(){document.dispatchEvent(new CustomEvent('near:period',{detail:{month:D.months[selected].month}}));}
let showRatios=false;
function renderHistory(){ $('historyHead').innerHTML='<tr><th>Period</th><th>Volume</th><th>Fees</th><th>Revenue</th><th>Buybacks</th>'+(showRatios?'<th>Fee rate</th><th>Revenue capture</th><th>Buybacks / issuance</th>':'')+'</tr>';$('historyRows').innerHTML=D.months.map(m=>`<tr><td>${label(m.month)}${m.complete?'':' <span class="pill">1–'+m.days+'</span>'}</td>${['volume','fees','revenue','buy'].map(k=>`<td>${k==='buy'?fmt(m[k]):usd(m[k])}${m.growth?.[k]!=null?`<small class="${m.growth[k]<0?'negative':''}">${signed(m.growth[k])}</small>`:''}</td>`).join('')}${showRatios?`<td>${pct(m.feeRate,3)}</td><td>${pct(m.captureRate)}</td><td>${m.mint&&m.buy!=null?pct(m.buy/m.mint):'—'}</td>`:''}</tr>`).join('');}
function corr(a,b){if(a.length<3)return null;const av=a.reduce((s,x)=>s+x,0)/a.length,bv=b.reduce((s,x)=>s+x,0)/b.length;let xy=0,xx=0,yy=0;a.forEach((x,i)=>{xy+=(x-av)*(b[i]-bv);xx+=(x-av)**2;yy+=(b[i]-bv)**2});return xx&&yy?xy/Math.sqrt(xx*yy):null;}
function market(){let rows=D.daily.filter(r=>['near','btc','eth'].every(k=>r[k]!=null));const n=$('marketWindow').value;if(n!=='all')rows=rows.slice(-Number(n));if(rows.length<2){$('marketSummary').textContent='Price history unavailable.';return}const first=rows[0],last=rows.at(-1),ret=k=>last[k]/first[k]-1;$('marketDate').textContent=last.date;chart('marketChart',['near','btc','eth'].map((k,i)=>({name:k.toUpperCase(),color:['#248365','#d48a43','#456bed'][i],values:rows.map(r=>r[k]/first[k]*100)})),rows.map(r=>r.date.slice(5)),n=>fmt(n));$('marketCards').innerHTML=['near','btc','eth'].map(k=>`<div class="card"><div class="label">${k.toUpperCase()}</div><div class="value">${usd(last[k])}</div><div class="delta ${ret(k)<0?'negative':''}">${signed(ret(k))} <span class="metricfoot">in selected period</span></div></div>`).join('')+`<div class="card"><div class="label">NEAR / BTC performance</div><div class="value">${((ret('near')-ret('btc'))*100).toFixed(1)}<small> pp</small></div><div class="metricfoot">Return difference</div></div>`;const a=[],b=[];for(let i=1;i<rows.length;i++){a.push(rows[i].near/rows[i-1].near-1);b.push(rows[i].btc/rows[i-1].btc-1)}const co=corr(a,b);$('marketSummary').textContent=`${first.date} – ${last.date} · First observation = 100`;$('marketRelative').innerHTML=[['NEAR minus BTC',((ret('near')-ret('btc'))*100).toFixed(1)+' pp'],['NEAR minus ETH',((ret('near')-ret('eth'))*100).toFixed(1)+' pp'],['NEAR–BTC correlation',co==null?'—':co.toFixed(2)]].map(([k,v])=>`<div><small>${k}</small><strong>${v}</strong></div>`).join('');}
function nextMonth(m,offset=1){const d=new Date(m+'-01T00:00:00Z');d.setUTCMonth(d.getUTCMonth()+offset);return d.toISOString().slice(0,7);}
function references(){const full=D.months.filter(m=>m.complete&&m.volume!=null&&m.fees!=null&&m.revenue!=null),last=full.at(-1),prior=full.at(-4),recent=full.slice(-3),fee=recent.reduce((s,x)=>s+x.fees,0)/recent.reduce((s,x)=>s+x.volume,0),cap=recent.reduce((s,x)=>s+x.revenue,0)/recent.reduce((s,x)=>s+x.fees,0),growth=prior?(last.volume/prior.volume)**(1/3)-1:0,issuance=D.months.filter(m=>m.complete&&m.mint!=null).at(-1),price=D.daily.filter(r=>r.near!=null).at(-1);return {last,recent,fee,cap,growth,issuance,price};}
function reset(){const r=references();$('g').value=(r.growth*100).toFixed(2);$('f').value=(r.fee*100).toFixed(5);$('c').value=(r.cap*100).toFixed(3);$('a').value=100;$('p').value=r.price.near.toFixed(4);$('i').value=Math.round(r.issuance.mint);$('assumptions').textContent=`Reference defaults: volume starts from ${label(r.last.month)}. Growth: trailing 3 monthly intervals. Fee/capture rates: volume-/fee-weighted ${label(r.recent[0].month)}–${label(r.last.month)}. Price: ${r.price.date} observation. Issuance: ${label(r.issuance.month)} carried forward as an assumption. Spending allocation: assumed 100%.`;forecast();}
function forecast(){const r=references(),ids=['g','f','c','a','p','i'],v=ids.map(id=>$(id).value.trim()===''?NaN:Number($(id).value));if(v.some(x=>!Number.isFinite(x))||v[0]<=-100||v[1]<0||v[1]>10||v[2]<0||v[2]>200||v[3]<0||v[3]>100||v[4]<=0||v[5]<=0){$('outcomes').innerHTML='<p>Enter valid values for all assumptions.</p>';$('forecastChart').innerHTML='';return}const [g,f,c,a,p,issuance]=v,labels=Array.from({length:36},(_,i)=>nextMonth(r.last.month,i+1)),variants=[{name:'Growth −5 pp',g:Math.max(-99,g-5),color:'#a7b7ac'},{name:'Your scenario',g,color:'#248365'},{name:'Growth +5 pp',g:g+5,color:'#d48a43'}];variants.forEach(s=>{s.values=labels.map((m,i)=>r.last.volume*(1+s.g/100)**(i+1)*f/100*c/100*a/100/p/issuance*100);s.first=s.values.findIndex(x=>x>=100);s.sustained=s.values.findIndex((x,i)=>i<34&&x>=100&&s.values[i+1]>=100&&s.values[i+2]>=100)});const chosen=variants[1];$('outcomes').innerHTML=`<div style="grid-column:1/-1"><small>First projected month above issuance</small><strong style="display:block;font-size:40px;font-weight:550;letter-spacing:-1.5px;margin:10px 0">${chosen.first<0?'Not reached within 36 months':label(labels[chosen.first])}</strong><span class="quiet">${chosen.sustained<0?'No 3-month sustained crossing in this period':'Three consecutive months from '+label(labels[chosen.sustained])}</span></div><div class="tablewrap" style="grid-column:1/-1;margin-top:18px"><table><thead><tr><th>Monthly volume growth</th><th>First crossing</th></tr></thead><tbody>${variants.map(q=>`<tr><td>${q.g.toFixed(2)}%${q===chosen?' · selected':''}</td><td>${q.first<0?'Not reached':label(labels[q.first])}</td></tr>`).join('')}</tbody></table></div>`;chart('forecastChart',variants.map(s=>({...s,values:s.values.slice(0,18)})),labels.slice(0,18).map(label),n=>fmt(n)+'%',100);$('forecastLimit').textContent='Modelled results · 36-month search · Chart: first 18 months. Issuance uses your entered assumption; newer verified records are not connected.';const train=D.months.filter(x=>x.complete&&x.month<r.last.month).slice(-3);if(train.length===3){const g0=(train[2].volume/train[0].volume)**.5-1,f0=train.reduce((s,x)=>s+x.fees,0)/train.reduce((s,x)=>s+x.volume,0),c0=train.reduce((s,x)=>s+x.revenue,0)/train.reduce((s,x)=>s+x.fees,0),pv=train[2].volume*(1+g0),pr=pv*f0*c0;$('backtest').textContent=`One-month holdout check: fitting only ${label(train[0].month)}–${label(train[2].month)} would project ${label(r.last.month)} volume of ${usd(pv)}, versus recorded ${usd(r.last.volume)} (${signed(pv/r.last.volume-1)} error). Revenue would be ${usd(pr)}, versus ${usd(r.last.revenue)} (${signed(pr/r.last.revenue-1)} error). This is one check, not evidence of reliable predictive accuracy. Buyback-spending allocation has not been fitted because arrival-date valuation is not verified expenditure.`;}}

function relationships(){const key=$('relationMetric').value,target=$('relationTarget').value,lag=Number($('relationLag').value),pairs=[];for(const m of D.months.filter(m=>m.complete&&m.growth?.[key]!=null)){const month=nextMonth(m.month,lag),first=D.daily.find(x=>x.date===month+'-01'),next=D.daily.find(x=>x.date===nextMonth(month)+'-01');if(!first?.near||!next?.near||!first?.btc||!next?.btc)continue;const near=next.near/first.near-1,btc=next.btc/first.btc-1;pairs.push({month:m.month,priceMonth:month,growth:m.growth[key],returns:target==='excess'?near-btc:near});}const c=corr(pairs.map(x=>x.growth),pairs.map(x=>x.returns));$('relationStats').innerHTML=`<div><small>Correlation</small><strong>${c==null?'—':c.toFixed(2)}</strong></div><div><small>Monthly observations</small><strong>${pairs.length}</strong></div><div><small>Timing</small><strong style="font-size:19px">${lag?'One month later':'Same month'}</strong></div>`;chart('relationChart',[{name:names[key]+' growth',color:'#248365',values:pairs.map(x=>x.growth*100)},{name:target==='excess'?'NEAR minus BTC':'NEAR return',color:'#d48a43',values:pairs.map(x=>x.returns*100)}],pairs.map(x=>label(x.month)),n=>fmt(n,1)+'%',0);$('relationLegend').innerHTML=`<span><i style="background:#248365"></i>${names[key]} growth</span><span><i style="background:#d48a43"></i>${target==='excess'?'NEAR minus BTC return':'NEAR return'}</span>`;$('activityAssociation').innerHTML='<div class="tablewrap"><table><thead><tr><th>Activity month</th><th>Growth</th><th>Price month</th><th>Return</th></tr></thead><tbody>'+pairs.map(x=>`<tr><td>${label(x.month)}</td><td>${signed(x.growth)}</td><td>${label(x.priceMonth)}</td><td>${signed(x.returns)}</td></tr>`).join('')+'</tbody></table></div>';}
function question(id){document.querySelectorAll('.research-pane').forEach(x=>x.hidden=x.id!==id);document.querySelectorAll('[data-question]').forEach(x=>x.classList.toggle('on',x.dataset.question===id));window.history.replaceState(null,'','#'+id);if(id==='relationships')relationships();else forecast();}
fetch('./data/performance.json').then(r=>{if(!r.ok)throw Error('Could not load data');return r.json()}).then(d=>{D=d;const page=document.body.dataset.page;if(page==='performance'){selected=d.months.length-1;$('period').innerHTML=d.months.map((m,i)=>`<option value="${i}">${label(m.month)}</option>`).join('');$('period').value=selected;$('period').onchange=e=>{selected=+e.target.value;render()};document.querySelector('.close').onclick=()=>$('detail').close();render();}if(page==='markets'){$('marketWindow').onchange=market;market();}if(page==='research'){['g','f','c','a','p','i'].forEach(id=>$(id).oninput=forecast);$('reset').onclick=reset;reset();document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>question(b.dataset.question));['relationMetric','relationTarget','relationLag'].forEach(id=>$(id).onchange=relationships);question(location.hash==='#relationships'?'relationships':'forecast');}}).catch(e=>{if($('loadError')){$('loadError').hidden=false;$('loadError').textContent='Data unavailable. '+e.message;}});
